WoWFA_Data[2050] = "معجزه‌ای انجام می‌دهد و یک متحد را به میزان $s1 شفا می‌دهد.\n\n|cFFFFFFFFوقتی Flash Heal$?a1246517[ یا Prayer of Healing][] کست می‌کنید، کول‌داون 6 ثانیه کاهش می‌یابد.|r"
WoWFA_En[8092] = "Blast the target's mind for $s1 Shadow damage.$?c1[ Costs a high amount of mana.][]$?s137033[\n\n|cFFFFFFFFGenerates ${$s2/100} Insanity.|r][]"
WoWFA_Data[8092] = "ذهن هدف را منفجر می‌کند و $s1 آسیب Shadow وارد می‌کند.$?c1[ مقدار زیادی Mana مصرف می‌کند.][]$?s137033[\n\n|cFFFFFFFF${$s2/100} Insanity تولید می‌کند.|r][]"
WoWFA_Data[8122] = "فریاد ذهنی سر می‌دهد و باعث می‌شود تمام دشمنان در فاصلهٔ 8 یارد فرار کنند و به‌مدت 8 ثانیه دچار سردرگمی شوند. آسیب ممکن است اثر را لغو کند."
WoWFA_Data[9484] = "یک دشمن Aberration یا Undead را به‌مدت 50 ثانیه زنجیر می‌کند و از تمام اقدامات و حرکت جلوگیری می‌کند. آسیب اثر را لغو می‌کند. حداکثر 1."
WoWFA_Data[10060] = "به‌مدت 15 ثانیه هدف را با قدرت پر می‌کند و Haste را 20% افزایش می‌دهد.\n\nفقط می‌توان آن را روی بازیکنان کست کرد."
WoWFA_En[14914] = "Consumes the enemy in Holy flames that cause $s1 Holy damage and an additional $o2 Holy damage over $d.$?a231687[ Stacks up to $u times.][]"
WoWFA_Data[14914] = "دشمن را در شعله‌های Holy می‌سوزاند که $s1 آسیب Holy و $o2 آسیب Holy اضافی در طول 7 ثانیه وارد می‌کنند.$?a231687[ تا 1 بار استک می‌شود.][]"
WoWFA_En[19236] = "Increases maximum health by $?s373450[${$s1+$373450s1}][$s1]% for $?a458718[${($458718s1+$s4)/1000}][${$s4/1000}] sec, and instantly heals you for that amount."
WoWFA_Data[19236] = "حداکثر سلامتی را برای $?a458718[20][10] ثانیه $?s373450[35][25]% افزایش می‌دهد و فوراً به همان اندازه شما را شفا می‌دهد."
WoWFA_Data[32375] = "Magic را در شعاع 15 یارد دیسپل می‌کند؛ تمام Magic مضر را از 5 هدف دوستانه و 1 اثر Magic سودمند را از 5 هدف دشمن حذف می‌کند. به‌قدری قوی است که Magicهایی را که به‌طور عادی قابل دیسپل نیستند حذف کند."
WoWFA_En[32379] = "A word of dark binding that inflicts $s2 Shadow damage to your target. If your target is not killed by Shadow Word: Death, you take backlash damage equal to $s6% of your maximum health.$?A364675[\n\nDamage increased by ${$s4+$364675s2}% to targets below ${$s3+$364675s1}% health.][\n\nDamage increased by $s4% to targets below $s3% health.]$?c3[][]$?s137033[\n\n|cFFFFFFFFGenerates ${$s5/100} Insanity.|r][]"
WoWFA_Data[32379] = "کلمه‌ای از قید تاریک که $s2 آسیب Shadow به هدف شما وارد می‌کند. اگر هدف شما با Shadow Word: Death کشته نشود، آسیب پس‌زدنی معادل 5% از حداکثر سلامتی‌تان دریافت می‌کنید.$?A364675[\n\nآسیب به اهداف با سلامتی کمتر از 50% به‌اندازهٔ 250% افزایش می‌یابد.][\n\nآسیب به اهداف با سلامتی کمتر از 20% به‌اندازهٔ 150% افزایش می‌یابد.]$?c3[][]$?s137033[\n\n|cFFFFFFFF${$s5/100} Insanity تولید می‌کند.|r][]"
WoWFA_Data[33206] = "تمام آسیب دریافتی یک هدف دوستانه را برای 8 ثانیه به‌اندازهٔ 40% کاهش می‌دهد. هنگام استان قابل کست است."
WoWFA_En[34433] = "Shadow Word: Death has a $s3% chance to summon a Shadowfiend for $s1 sec when damaging targets below $s2% health.\n\n$@spellicon1280172 $@spellname1280172\nSummons a Shadowfiend to attack your target for $1280172d.$?c3[\n\n|cFFFFFFFFGenerates ${$200010s1/100} Insanity each time the Shadowfiend attacks.|r][\n\n|cFFFFFFFFGenerates ${$343727m1/10}.1% mana each time the Shadowfiend attacks.|r]"
WoWFA_Data[34433] = "Shadow Word: Death هنگام آسیب زدن به اهداف با سلامتی کمتر از 20%، 40% شانس دارد برای 5 ثانیه یک Shadowfiend احضار کند.\n\n Shadowfiend\nبرای 5 ثانیه یک Shadowfiend احضار می‌کند تا به هدف شما حمله کند.$?c3[\n\n|cFFFFFFFFShadowfiend با هر حمله 1 Insanity تولید می‌کند.|r][\n\n|cFFFFFFFFShadowfiend با هر حمله 0.5% Mana تولید می‌کند.|r]"
WoWFA_En[34861] = "Releases miraculous light at a target location, healing up to $s2 allies within $a1 yds for $s1.\n\n|cFFFFFFFFCooldown reduced by $s3 sec when you cast Prayer of Healing.|r"
WoWFA_Data[34861] = "در مکان هدف نوری معجزه‌آسا آزاد می‌کند و تا 5 متحد در فاصلهٔ 10 یارد را به میزان $s1 شفا می‌دهد.\n\n|cFFFFFFFFوقتی Prayer of Healing کست می‌کنید، کول‌داون 6 ثانیه کاهش می‌یابد.|r"
WoWFA_Data[47515] = "شفاهای Critical Strike مستقیم، سپری محافظ روی هدف ایجاد می‌کنند که 30% از مقدار شفا شده را جذب می‌کند. 15 ثانیه دوام دارد."
WoWFA_Data[47788] = "روحی محافظ را فرا می‌خواند که به‌مدت 10 ثانیه مراقب هدف دوستانه باشد و شفا دریافتی او را 60% افزایش دهد. اگر هدف در آستانهٔ مرگ قرار گیرد، روح قربانی خود می‌شود و هدف را به 40% سلامتی بازمی‌گرداند.\n\nهنگام استان قابل کست است. نمی‌تواند هدف را از آسیب عظیم نجات دهد."
WoWFA_Data[55676] = "Psychic Scream باعث می‌شود دشمنان به‌جای فرار از ترس، در جای خود لرزانند."
WoWFA_Data[62618] = "سدی مقدسی در مکان هدف احضار می‌کند که برای 10 ثانیه از تمام متحدان محافظت می‌کند؛ تمام آسیب دریافتی را 20% کاهش می‌دهد و از تأخیر در کست اسپل‌ها بر اثر آسیب جلوگیری می‌کند."
WoWFA_En[64129] = "$?c2[Prayer of Mending][Power Word: Shield] and Leap of Faith increase your target's movement speed by $65081s1% for $65081d."
WoWFA_Data[64129] = "$?c2[Prayer of Mending][Power Word: Shield] و Leap of Faith سرعت حرکت هدف شما را برای 3 ثانیه به‌اندازهٔ 40% افزایش می‌دهند."
WoWFA_En[64843] = "Heals all party or raid members within $64844A1 yards for ${5*$64844s1} over $d. Each heal increases all targets' healing taken by $64844s2% for $64844d, stacking.\n\nYou gain Guardian Spirit while channeling Divine Hymn.\n\nHealing reduced beyond $s5 targets."
WoWFA_Data[64843] = "تمام اعضای پارتی یا رید در فاصلهٔ 40 یارد را در طول 5 ثانیه به میزان ${5*$64844s1} شفا می‌دهد. هر شفا، شفا دریافتی تمام اهداف را به‌صورت استک‌شونده برای 15 ثانیه به‌اندازهٔ 4% افزایش می‌دهد.\n\nدر طول کست کردن Divine Hymn، Guardian Spirit به‌دست می‌آورید.\n\nشفای بیش از 5 هدف کاهش می‌یابد."
WoWFA_Data[73325] = "روح یک عضو پارتی یا رید را به سمت خود می‌کشد و او را فوراً درست مقابل شما قرار می‌دهد."
WoWFA_En[73510] = "Shadowy Apparitions that float towards your primary target explode, dealing $1231479s1 Shadow damage to all enemies within $1231479A1 yds.\n\nDamage reduced beyond $s1 targets."
WoWFA_Data[73510] = "Shadowy Apparitionهایی که به سمت هدف اصلی شما شناور می‌شوند منفجر می‌شوند و به تمام دشمنان در فاصلهٔ 8 یارد $1231479s1 آسیب Shadow وارد می‌کنند.\n\nآسیب پس از 5 هدف کاهش می‌یابد."
WoWFA_Data[81749] = "Power Word: Shield، Flash Heal، Shadow Mend، Plea و Power Word: Radiance به‌مدت 15 ثانیه روی هدف شما Atonement اعمال می‌کنند.\n\nآسیب اسپل‌های شما، تمام اهداف متأثر از Atonement را به‌اندازهٔ 46% از آسیب واردشده شفا می‌دهد. اگر بیش از 5 هدف شفا داده شود، شفا کاهش می‌یابد.\n\nخارج از رید، شفا به‌اندازهٔ 40% افزایش می‌یابد."
WoWFA_En[88625] = "Chastises the target for $s1 Holy damage and $?s200199[stuns][incapacitates] them for $?s200199[$200200d][$200196d].$?s63733[\n\n|cFFFFFFFFCooldown reduced by $s2 sec when you cast Smite or Holy Nova.|r][]"
WoWFA_Data[88625] = "هدف را با $s1 آسیب Holy سرزنش می‌کند و او را به‌مدت $?s200199[4 ثانیه][4 ثانیه] $?s200199[استان][ناتوان] می‌کند.$?s63733[\n\n|cFFFFFFFFوقتی Smite یا Holy Nova کست می‌کنید، کول‌داون 4 ثانیه کاهش می‌یابد.|r][]"
WoWFA_Data[108942] = "فعال کردن Fade تمام اثرات کاهش‌دهندهٔ سرعت حرکت را حذف می‌کند."
WoWFA_Data[108945] = "وقتی حمله‌ای سلامتی شما را به زیر 30% برساند، سپری جذب آسیب معادل 25% از حداکثر سلامتی‌تان برای 20 ثانیه به‌دست می‌آورید. این اتفاق بیش از یک‌بار در هر 90 ثانیه رخ نمی‌دهد."
WoWFA_En[109186] = "Your healing spells and Smite have a $s1% chance to make your next $?c1[Flash Heal or Shadow Mend][Flash Heal]$?a1247178[ or Prayer of Healing][] instant and cost $?a137030[$114255s4]?a137031[$114255s2][$114255s3]% less mana. Stacks to $114255u."
WoWFA_Data[109186] = "اسپل‌های شفای شما و Smite 8% شانس دارند که $?c1[Flash Heal یا Shadow Mend][Flash Heal]$?a1247178[ یا Prayer of Healing][] بعدی شما را فوری کنند و هزینهٔ Mana آن را $?a137030[50]?a137031[50][50]% کاهش دهند. تا 2 استک می‌شود."
WoWFA_En[120517] = "Creates a ring of Holy energy around you that quickly expands to a $s2 yd radius, healing allies for $120692s1 and dealing $<holyhalodamage> Holy damage to enemies.\n\nHealing reduced beyond $s1 targets."
WoWFA_Data[120517] = "حلقه‌ای از انرژی Holy در اطراف شما ایجاد می‌کند که به‌سرعت تا شعاع 40 یارد گسترش می‌یابد؛ متحدان را به میزان $120692s1 شفا می‌دهد و به دشمنان $<holyhalodamage> آسیب Holy وارد می‌کند.\n\nشفای بیش از 6 هدف کاهش می‌یابد."
WoWFA_En[120644] = "Creates a ring of Shadow energy around you that quickly expands to a $s2 yd radius, healing allies for $120692s1 and dealing $<shadowhalodamage> Shadow damage to enemies. Healing reduced beyond $s1 targets.$?s137033[\n\n|cFFFFFFFFGenerates ${$m5/100} Insanity.|r][]"
WoWFA_Data[120644] = "حلقه‌ای از انرژی Shadow در اطراف شما ایجاد می‌کند که به‌سرعت تا شعاع 40 یارد گسترش می‌یابد؛ متحدان را به میزان $120692s1 شفا می‌دهد و به دشمنان $<shadowhalodamage> آسیب Shadow وارد می‌کند. شفای بیش از 6 هدف کاهش می‌یابد.$?s137033[\n\n|cFFFFFFFF5 Insanity تولید می‌کند.|r][]"
WoWFA_En[121536] = "Places a feather at the target location, granting the first ally to walk through it $121557s1% increased movement speed for $121557d.$?a440670[ When an ally walks through a feather, you are also granted $440670s3% of its effect.][] Only 3 feathers can be placed at one time."
WoWFA_Data[121536] = "یک پَر در مکان هدف قرار می‌دهد و به اولین متحدی که از آن عبور کند، 40% سرعت حرکت اضافه برای 5 ثانیه می‌دهد.$?a440670[ وقتی متحدی از یک پَر عبور کند، شما نیز $440670s3% از اثر آن را دریافت می‌کنید.][] در هر لحظه فقط می‌توان 3 پَر قرار داد."
