WoWFA_Data[197862] = "Evangelism اثرات شفا و جذب شما را برای 18 ثانیه به‌اندازهٔ 15% افزایش می‌دهد."
WoWFA_Data[198068] = "Shadow Word: Pain شانس دارد Penance بعدی شما را با Shadow تقویت کند و اثربخشی آن را 30% افزایش دهد."
WoWFA_Data[199484] = "اسپل‌های آسیب مستقیم شما، 20% از آسیب خود را به تمام اهداف دیگر متأثر از Vampiric Touch شما در فاصلهٔ 40 یارد وارد می‌کنند.\n\nروی آسیب Shadowy Apparitionها، Shadow Word: Pain و Vampiric Touch اعمال نمی‌شود."
WoWFA_Data[200128] = "25% از شفای Flash Heal به هدف قبلی‌ای که با این اسپل‌ها شفا داده بودید بازتاب می‌یابد."
WoWFA_En[200183] = "$?s235587[Gain a charge][Reset the cooldown] of your Holy Words, and enter a pure Holy form for $d, increasing the cooldown reductions to your Holy Words by $s1% and reducing their cost by $s6%."
WoWFA_Data[200183] = "$?s235587[یک شارژ برای Holy Wordهای خود به‌دست می‌آورید][کول‌داون Holy Wordهای خود بازنشانی می‌شود] و به‌مدت 20 ثانیه وارد فرمی خالص از Holy می‌شوید؛ کاهش کول‌داون Holy Wordهای شما 200% افزایش می‌یابد و هزینهٔ آن‌ها 70% کاهش می‌یابد."
WoWFA_Data[200199] = "Holy Word: Chastise هدف را به‌مدت 4 ثانیه استان می‌کند و با آسیب شکسته نمی‌شود."
WoWFA_Data[200209] = "وقتی Guardian Spirit هدف را از مرگ نجات دهد، منقضی نمی‌شود.\n\nوقتی Guardian Spirit بدون نجات هدف از مرگ منقضی شود، کول‌داون باقی‌ماندهٔ آن به 60 ثانیه کاهش می‌یابد."
WoWFA_En[205364] = "Controls a mind up to 1 level above yours for $d while still controlling your own mind. Does not work versus Demonic, Mechanical, or Undead beings$?a205477[][ or players]. This spell shares diminishing returns with other disorienting effects."
WoWFA_Data[205364] = "به‌مدت 30 ثانیه ذهنی حداکثر 1 سطح بالاتر از خودتان را کنترل می‌کند، در حالی‌که ذهن خودتان را نیز تحت کنترل دارید. روی موجودات Demonic، Mechanical یا Undead$?a205477[][ یا بازیکنان] کار نمی‌کند. این اسپل با سایر اثرات سردرگمی‌آور diminishing returns مشترک دارد."
WoWFA_Data[213634] = "تمام اثرات Disease را از یک هدف دوستانه حذف می‌کند."
WoWFA_Data[215768] = "آسیب Smite و Penance به‌اندازهٔ 8% افزایش می‌یابد و Penance سرعت حرکت هدف شما را برای 2 ثانیه به‌اندازهٔ 25% افزایش یا کاهش می‌دهد."
WoWFA_En[228260] = "Bombards your target with a Void Volley and twists your Shadowform with void magic, increasing your spell damage by $194249s1% for $194249d. \n\nDuring Voidform, Void Volley replaces this spell and can be used up to $s3 times.\n\n$@spellicon1242173 $@spellname1242173\n$@spelldesc1242173"
WoWFA_Data[228260] = "به‌مدت 20 ثانیه با یک Void Volley به هدف شما رگبار می‌بارد و Shadowform شما را با جادوی Void پیچ می‌دهد؛ آسیب اسپل شما را 20% افزایش می‌دهد. \n\nدر طول Voidform، Void Volley جای این اسپل را می‌گیرد و می‌توان حداکثر 3 بار از آن استفاده کرد.\n\n Void Volley\nReleases a volley of pure void energy, firing 10 bolts at your target and 1 $L:bolts;bolt at all enemies within 10 yards of your target for $1242189s1 Shadow damage.\n\n|cFFFFFFFFGenerates 10 Insanity.|r"
WoWFA_En[231682] = "Smite prevents the next $<shield> damage dealt by the enemy."
WoWFA_Data[231682] = "Smite از $<shield> آسیب بعدیِ دشمن جلوگیری می‌کند."
WoWFA_En[235587] = "Holy Word: Serenity$?a?a1246517[ gains][ and Holy Word: Sanctify gain] an additional charge."
WoWFA_Data[235587] = "Holy Word: Serenity$?a?a1246517[ یک شارژ اضافی به‌دست می‌آورد][ و Holy Word: Sanctify یک شارژ اضافی به‌دست می‌آورند]."
WoWFA_Data[238063] = "Atonement آسیب دریافتی را 2% کاهش می‌دهد."
WoWFA_Data[238100] = "کول‌داون Desperate Prayer را به‌اندازهٔ 20 ثانیه کاهش می‌دهد."
WoWFA_Data[238135] = "Power Word: Shield 20% آسیب اضافی جذب می‌کند و 5 ثانیه بیشتر دوام می‌آورد."
WoWFA_En[238136] = "When Holy Word: Serenity $?a1246517[finishes its][or Holy Word: Sanctify finish their] cooldown, you emit a burst of light that heals up to $s1 injured targets within $243241A1 yards for $243241s1."
WoWFA_Data[238136] = "وقتی کول‌داون Holy Word: Serenity $?a1246517[تمام شود][یا Holy Word: Sanctify تمام شود]، انفجاری از نور آزاد می‌کنید که تا 5 هدف زخمی در فاصلهٔ 40 یارد را به میزان $243241s1 شفا می‌دهد."
WoWFA_Data[238558] = "Vampiric Touch همچنین Shadow Word: Pain را روی هدف اعمال می‌کند. Shadow Word: Pain 5 ثانیه بیشتر دوام می‌آورد."
WoWFA_En[263165] = "Channel a torrent of void energy into the target, dealing $o Shadow damage over $d and tearing open an $@spellname447444.\n\n$@spellicon447444 $@spellname447444\n$@spelldesc447444\n\n|cFFFFFFFFGenerates ${$289577s1*$289577s2/100} Insanity over the duration.|r"
WoWFA_Data[263165] = "جریانی از انرژی Void را در هدف کست می‌کند؛ در طول 3 ثانیه، $o آسیب Shadow وارد می‌کند و یک Entropic Rift می‌گشاید.\n\n Entropic Rift\n$?c3[شکافی می‌گشایید][Mind Blast شکافی Entropic می‌گشاید] که به‌مدت 8 ثانیه دشمن را تعقیب می‌کند. دشمنانی که در مسیر آن گرفتار شوند، تا زمانی که در دسترس آن باشند هر 1 ثانیه $447448s1 آسیب Shadow متحمل می‌شوند.\n\n|cFFFFFFFFدر طول مدت، 24 Insanity تولید می‌کند.|r"
WoWFA_En[288733] = "Dispersion heals you for an additional $<intangheal>% of your maximum health over its duration and its cooldown is reduced by ${$s1/-1000} sec."
WoWFA_Data[288733] = "Dispersion در طول مدت خود، $<intangheal>% اضافی از حداکثر سلامتی شما را شفا می‌دهد و کول‌داون آن 30 ثانیه کاهش می‌یابد."
WoWFA_Data[321291] = "اگر هدفی طی 7 ثانیه پس از برخورد Shadow Word: Death بمیرد، 8 Insanity تولید می‌کنید.\n\nوقتی Shadow Word: Death نتواند هدفی با سلامتی کمتر از 20% را بکشد، کول‌داون آن بازنشانی می‌شود. این اتفاق بیش از یک‌بار در هر 10 ثانیه رخ نمی‌دهد."
WoWFA_Data[322115] = "Power Word: Radiance یک شارژ اضافی به‌دست می‌آورد."
WoWFA_En[335467] = "A word of madness haunts the target's mind, dealing $s1 Shadow damage instantly plus an additional $o3 Shadow damage over $d. Heals you for ${$e1*100}% of damage dealt.\n\nWhen reapplied to a target, all remaining damage is added to the new effect."
WoWFA_Data[335467] = "کلمه‌ای از جنون، ذهن هدف را تسخیر می‌کند؛ بلافاصله $s1 آسیب Shadow و به‌علاوهٔ $o3 آسیب Shadow اضافی در طول 6 ثانیه وارد می‌کند. 30% از آسیب واردشده به شما شفا می‌دهد.\n\nوقتی دوباره روی هدفی اعمال شود، تمام آسیب باقی‌مانده به اثر جدید اضافه می‌شود."
WoWFA_En[341167] = "Reduces the mana cost of $?a137033[Purify Disease][Purify] and Mass Dispel by $s1% and Dispel Magic by $s2%.\n"
WoWFA_Data[341167] = "هزینهٔ Mana $?a137033[Purify Disease][Purify] و Mass Dispel را 50% و Dispel Magic را 10% کاهش می‌دهد."
WoWFA_Data[341240] = "Voidform آسیب اسپل شما را 5% دیگر افزایش می‌دهد و 2 بار اضافی Void Volley اعطا می‌کند."
WoWFA_En[341491] = "Shadow Word: Madness conjures Shadowy Apparitions that float towards all targets afflicted by your Vampiric Touch for $413231s1 Shadow damage."
WoWFA_Data[341491] = "Shadow Word: Madness، Shadowy Apparitionهایی احضار می‌کند که به سمت تمام اهداف متأثر از Vampiric Touch شما شناور می‌شوند و $413231s1 آسیب Shadow وارد می‌کنند."
WoWFA_Data[341997] = "شفای شما روی متحدان دارای Renew شما 10% افزایش می‌یابد."
WoWFA_En[368275] = "$s1% of $?c1[Flash Heal or Shadow Mend][Flash Heal] healing on other targets also heals you."
WoWFA_Data[368275] = "20% از شفای $?c1[Flash Heal یا Shadow Mend][Flash Heal] روی اهداف دیگر، شما را نیز شفا می‌دهد."
WoWFA_Data[372307] = "آسیب Holy Fire را 30% افزایش می‌دهد.\n\nHoly Fire 75% از آسیب اولیهٔ خود را به تمام دشمنان نزدیک در فاصلهٔ 12 یاردی هدف شما وارد می‌کند. آسیب پس از 5 هدف کاهش می‌یابد."
WoWFA_Data[372370] = "در طول کست کردن Divine Hymn، هر 1 ثانیه 2 استک Prayer of Mending روی حداکثر 3 متحد در برد آن قرار می‌دهید."
WoWFA_Data[372616] = "Holy Word: Chastise باعث می‌شود 2 کست بعدی Holy Fire شما فوری باشند، Mana مصرف نکنند و کول‌داون ایجاد نکنند.\n\nتمدید Holy Fire روی یک هدف اکنون مدت آن را 7 ثانیه تمدید می‌کند."
WoWFA_Data[372969] = "هر شلیک متوالی Penance در طول کست، 5% آسیب و شفای بیشتری وارد می‌کند."
WoWFA_Data[372972] = "Mind Blast 100% شانس دارد Power of the Dark Side اعطا کند و 20% آسیب اضافی وارد می‌کند."
WoWFA_Data[372991] = "Pain Suppression همچنین هدف شما را به‌اندازهٔ 15% از حداکثر سلامتی‌اش شفا می‌دهد و Atonement اعمال می‌کند."
WoWFA_Data[373003] = "Shadow Word: Pain 5% آسیب اضافی وارد می‌کند و وقتی روی هدف آن Penance کست می‌کنید، به 1 هدف اضافی گسترش می‌یابد."
WoWFA_Data[373035] = "Pain Suppression یک شارژ اضافی به‌دست می‌آورد.\n\nPower Word: Shield کول‌داون Pain Suppression را 3 ثانیه کاهش می‌دهد."
WoWFA_Data[373049] = "Atonementهای اعطاشده توسط Power Word: Shield، 4 ثانیه بیشتر دوام می‌آورند."
WoWFA_Data[373054] = "وقتی Atonement توسط اسپل‌های Shadow فعال شود، 10% بیشتر شفا می‌دهد."
WoWFA_Data[373180] = "Power Word: Radiance باعث می‌شود Penance بعدی شما 3 شلیک اضافی شلیک کند؛ تا 2 شارژ استک می‌شود."
WoWFA_Data[373202] = "Mind Blast 8% شانس دارد Shadow Word: Madness بعدی شما را بدون هزینهٔ Insanity کند و 20% آسیب اضافی وارد کند."
WoWFA_Data[373212] = "وقتی Shadow Word: Pain، Shadow Word: Madness و Vampiric Touch روی یک هدف فعال باشند، Mind Blast، Void Torrent، Mind Flay و Void Volley شما 20% آسیب بیشتری وارد می‌کنند."
WoWFA_Data[373218] = "Leech شما را 2% افزایش می‌دهد."
WoWFA_Data[373223] = "Shadow Word: Death به شما 50% آسیب کمتری وارد می‌کند."
WoWFA_En[373273] = "After conjuring Shadowy Apparitions, gain a stack of Idol of Yogg-Saron. At $s1 stacks, you summon a Thing from Beyond that casts Void Spike at nearby enemies for $373277d.\n\n$@spellicon373279 $@spellname373279\n$@spelldesc373279"
WoWFA_Data[373273] = "پس از احضار Shadowy Apparitionها، یک استک Idol of Yogg-Saron به‌دست می‌آورید. در 20 استک، یک Thing from Beyond احضار می‌کنید که به‌مدت 20 ثانیه روی دشمنان نزدیک Void Spike کست می‌کند.\n\n Void Spike\nHurls a bolt of dark magic, dealing 20 Shadow damage and ${$s1*$s2/100} Shadow damage to all enemies within 10 yards of the target. Damage reduced beyond 5 targets."
WoWFA_En[373280] = "You create Horrific Visions when casting harmful spells on enemies.\n\nAt $s1 stacks of Horrific Visions, your target sees a nightmare, dealing $1243105s1 Shadow damage and granting you ${$1243113o1/100} Insanity over $1243113s2 sec.\n\nAt $s2 stacks, your target witnesses a vision of N'Zoth, dealing $1243106s1 Shadow damage and granting you ${$1243114o1/100} Insanity over $1243114s2 sec."
WoWFA_Data[373280] = "هنگام کست کردن اسپل‌های مضر روی دشمنان، Horrific Vision ایجاد می‌کنید.\n\nدر 50 استک Horrific Visions، هدف شما کابوسی می‌بیند که $1243105s1 آسیب Shadow وارد می‌کند و طی 3 ثانیه 2.03 Insanity به شما می‌دهد.\n\nدر 100 استک، هدف شما شاهد رؤیایی از N'Zoth می‌شود که $1243106s1 آسیب Shadow وارد می‌کند و طی 3 ثانیه 6.1 Insanity به شما می‌دهد."
WoWFA_Data[373310] = "وقتی Shadowfiend، Mindbender یا Voidwraith فعال است، Haste شما 10% افزایش می‌یابد."
WoWFA_En[373427] = "$?a137032[Penance, ][]Mind Blast and Shadow Word: Death cause your Shadowfiend, Mindbender, and Voidwraith to teleport behind your target, slashing up to $s1 nearby enemies for $<value> Shadow damage and extending their durations by ${$s2/1000}.1 sec."
WoWFA_Data[373427] = "$?a137032[Penance، ][]Mind Blast و Shadow Word: Death باعث می‌شوند Shadowfiend، Mindbender و Voidwraith شما پشت هدف تله‌پورت کنند، تا 5 دشمن نزدیک را با $<value> آسیب Shadow دریده و مدت آن‌ها را 0.7 ثانیه تمدید کنند."
WoWFA_Data[373446] = "Fade آسیب دریافتی شما را 10% کاهش می‌دهد."
WoWFA_Data[373450] = "حداکثر سلامتی به‌دست‌آمده از Desperate Prayer را 10% افزایش می‌دهد."
WoWFA_En[373456] = "While above $s2% health, the cast time of your $?c1[Flash Heal, Shadow Mend, and Smite are]?c2[Flash Heal, Prayer of Healing, and Smite are][Flash Heal is] reduced by $s1%."
WoWFA_Data[373456] = "وقتی سلامتی شما بالای 75% است، زمان کست $?c1[Flash Heal، Shadow Mend و Smite]?c2[Flash Heal، Prayer of Healing و Smite][Flash Heal]ِ شما 5% کاهش می‌یابد."
WoWFA_Data[373466] = "Power Infusion وقتی روی یک متحد استفاده می‌شود، اثر خود را با 100% مقدار به شما نیز می‌دهد. \n\nاگر متحدی هدف گرفته نشده باشد، اثر خود را با 100% مقدار به یک متحد نزدیک می‌دهد و آسیب‌زننده‌ها را در اولویت قرار می‌دهد."
WoWFA_Data[375767] = "Shadow Word: Madness باعث می‌شود Shadow Word: Pain و Vampiric Touch شما برای 3 ثانیه روی تمام اهداف 40% سریع‌تر آسیب وارد کنند."
WoWFA_Data[375888] = "آسیب دوره‌ای Shadow Word: Pain شانس دارد Mind Blast بعدی شما را فوری کند و کول‌داون آن را نادیده بگیرد."
WoWFA_Data[375994] = "آسیب Mind Flay را 25% افزایش می‌دهد."
WoWFA_Data[377065] = "وقتی در حداکثر سلامتی هستید، شفای Vampiric Touch و Shadow Word: Madness به‌جای آن به همان اندازه به شما سپر می‌دهد. این سپر نمی‌تواند از 10% حداکثر سلامتی شما بیشتر شود."
WoWFA_En[377349] = "Mind Flay has a chance to spawn a Void Tendril that channels Mind Flay or Void Lasher that channels Mind Sear at your target.\n\n$@spellicon193473 $@spellname193473\n$@spelldesc193473\n\n$@spellicon394976 $@spellname394976\n$@spelldesc394976"
WoWFA_Data[377349] = "Mind Flay شانس دارد یک Void Tendril که Mind Flay را کست می‌کند یا یک Void Lasher که Mind Sear را کست می‌کند، روی هدف شما برویاند.\n\n Mind Flay\nAssaults the target's mind with Shadow energy, causing $o1 Shadow damage over 10 ثانیه and slowing their movement speed by 30%.\n\n|cFFFFFFFFGenerates 5 Insanity over the duration.|r\n\n Mind Sear\nCorrosive shadow energy radiates from the target, dealing ${$394979s2*$s2} Shadow damage over 10 ثانیه to all enemies within 10 yards of the target. Damage reduced beyond 5 targets.\n\n|cFFFFFFFFGenerates 5 Insanity over the duration.|r"
WoWFA_Data[390620] = "کول‌داون Leap of Faith را به‌اندازهٔ 30 ثانیه کاهش می‌دهد."
WoWFA_Data[390632] = "Purify علاوه بر این، تمام اثرات Disease را حذف می‌کند."
WoWFA_Data[390667] = "تمام آسیب Magic دریافتی را 3% کاهش می‌دهد."
WoWFA_En[390670] = "Reduces the cooldown of Fade by ${$s1/-1000)} sec."
WoWFA_Data[390670] = "کول‌داون Fade را به‌اندازهٔ ${$s1/-1000)} ثانیه کاهش می‌دهد."
WoWFA_En[390676] = "Reduces your target's physical damage taken by $390677s1% for $390677d after a critical heal with $?c1[Flash Heal, Shadow Mend, or Penance]?c2[Flash Heal or Holy Word: Serenity][Flash Heal]."
WoWFA_Data[390676] = "پس از یک شفای Critical Strike با $?c1[Flash Heal، Shadow Mend یا Penance]?c2[Flash Heal یا Holy Word: Serenity][Flash Heal]، آسیب Physical دریافتی هدف شما را برای 15 ثانیه به‌اندازهٔ 5% کاهش می‌دهد."
WoWFA_Data[390684] = "کول‌داون Power Word: Radiance را به‌اندازهٔ 3 ثانیه کاهش می‌دهد."
WoWFA_Data[390685] = "زمان کست Power Word: Radiance را 30% کاهش می‌دهد و باعث می‌شود Atonement را به‌اندازهٔ 10% اضافی از مدت عادی‌اش اعمال کند."
WoWFA_Data[390686] = "هر شلیک Penance، مدت Shadow Word: Pain روی دشمنان برخوردکرده را 1.5 ثانیه تمدید می‌کند."
WoWFA_Data[390689] = "آسیب Shadow Word: Pain را 8% افزایش می‌دهد و مدت آن را 2 ثانیه بیشتر می‌کند."
WoWFA_Data[390691] = "کست کردن Power Word: Shield، Haste شما را برای 4 ثانیه به‌اندازهٔ 5% افزایش می‌دهد."
WoWFA_Data[390693] = "Flash Heal، Shadow Mend، Power Word: Shield، Penance و Power Word: Radiance 20% شانس بیشتری برای شفای Critical Strike دارند."
WoWFA_En[390786] = "Your Penance bolts increase the absorb of your next Power Word: Shield by $390787s2%.\n\nStacks up to $390787U times."
WoWFA_Data[390786] = "شلیک‌های Penance شما، جذب Power Word: Shield بعدی‌تان را 3% افزایش می‌دهند.\n\nتا $390787U بار استک می‌شود."
WoWFA_Data[390832] = "Mind Blast و Shadow Word: Death 1 ثانیه از Shadow Word: Pain را مصرف می‌کنند و آسیبی معادل 300% از مقدار مصرف‌شده وارد می‌کنند."
WoWFA_Data[390919] = "مقدار آسیب لازم برای شکستن Psychic Scream شما را 25% افزایش می‌دهد."
WoWFA_Data[390954] = "شانس Critical Strike Flash Heal و Prayer of Healing را 15% افزایش می‌دهد."
WoWFA_Data[390967] = "شفای Mastery: Echo of Light شما را 5% و Renew شما را 13% افزایش می‌دهد."
WoWFA_Data[390972] = "پس از آسیب زدن یا شفا دادن به هدفی با سلامتی کمتر از 35%، برای 8 ثانیه 5% آسیب و شفای اضافی به‌دست می‌آورید."
WoWFA_Data[390977] = "Prayer of Mending 2 بار اضافی می‌پرد."
WoWFA_En[390992] = "Flash Heal reduces the cast time of your next Prayer of Healing within $390993d by $390993s2% and increases its healing done by $390993s1%.\n\nCan accumulate up to $390993U charges."
WoWFA_Data[390992] = "Flash Heal، زمان کست Prayer of Healing بعدی شما را طی 20 ثانیه به‌اندازهٔ 30% کاهش می‌دهد و شفای آن را 18% افزایش می‌دهد.\n\nتا $390993U شارژ می‌تواند انباشته شود."
WoWFA_En[390994] = "Prayer of Mending $?S120517&?a1246517[and creating a Halo ][]reduces the cooldown of Holy Word: Serenity by $s2 sec.\n\n$?S120517&!?a1246517[Creating a Halo reduces the cooldown of Holy Word: Sanctify by $s1 sec.\n\n][]Holy Fire reduces the cooldown of Holy Word: Chastise by $s3 sec."
WoWFA_Data[390994] = "Prayer of Mending $?S120517&?a1246517[و ایجاد Halo ][]کول‌داون Holy Word: Serenity را 4 ثانیه کاهش می‌دهد.\n\n$?S120517&!?a1246517[ایجاد Halo کول‌داون Holy Word: Sanctify را 4 ثانیه کاهش می‌دهد.\n\n][]Holy Fire کول‌داون Holy Word: Chastise را 4 ثانیه کاهش می‌دهد."
WoWFA_En[391090] = "Mind Flay damage increases the critical strike chance of Mind Blast by $s1%, stacking up to $391092U times.\n\nLasts $391092d."
WoWFA_Data[391090] = "آسیب Mind Flay، شانس Critical Strike Mind Blast را 8% افزایش می‌دهد؛ تا $391092U بار استک می‌شود.\n\n10 ثانیه دوام دارد."
WoWFA_Data[391099] = "آسیب دوره‌ای اسپل‌های شما را 6% افزایش می‌دهد."
WoWFA_Data[391124] = "پس از منقضی شدن Spirit of Redemption، بر اساس شفایی که در طول آن انجام داده‌اید، با حداکثر 100% سلامتی احیا می‌شوید. پس از احیا، به‌مدت 10 دقیقه نمی‌توانید از Spirit of Redemption بهره ببرید."
WoWFA_Data[391151] = "شانس Critical Strike Mind Blast، Mind Flay و Shadow Word: Death را 4% افزایش می‌دهد و آسیب Critical Strike آن‌ها را 20% افزایش می‌دهد."
WoWFA_Data[391186] = "Prayer of Mending 15% شانس دارد هنگام پرش به هدف جدید، شارژی مصرف نکند."
WoWFA_Data[391209] = "هدف اصلی Prayer of Healing به‌اندازهٔ 125% بیشتر شفا می‌یابد."
WoWFA_Data[391228] = "Vampiric Touch 20% آسیب اضافی وارد می‌کند و هر بار که آسیب می‌زند، شانس دارد 1 Insanity تولید کند."
WoWFA_Data[391233] = "Prayer of Mending به‌ازای هر پرش باقی‌مانده، 4% بیشتر شفا می‌دهد."
WoWFA_Data[391284] = "آسیب Shadow Word: Pain شما شانس دارد Shadowy Apparitionهایی ایجاد کند که به سمت تمام اهداف متأثر از Vampiric Touch شما شناور می‌شوند. \n\nCritical Strikeها شانس را 100% افزایش می‌دهند."
WoWFA_Data[391381] = "شفای اهداف دوستانه با سلامتی 50% یا کمتر را 10% افزایش می‌دهد."
WoWFA_Data[391399] = "آسیب Mind Flay به‌اندازهٔ 15% و تولید Insanity به‌اندازهٔ 30% افزایش می‌یابد."
WoWFA_Data[392507] = "آسیب Shadow Word: Death به‌اندازهٔ 25% افزایش می‌یابد.\n\nShadow Word: Death آسیب و پاداش‌های تلنت خود را روی اهداف با سلامتی کمتر از 35% به‌جای 20% اعمال می‌کند."
WoWFA_Data[392988] = "Holy Wordهای شما تصویری از یک Naaru در کنار شما احضار می‌کنند. به‌مدت 9 ثانیه، هر بار که اسپل شفا یا آسیب کست می‌کنید، Naaru نیز اسپلی مشابه کست می‌کند.\n\nاگر قبلاً تصویری احضار شده باشد، به‌جای آن همان تصویر تقویت می‌شود."
WoWFA_En[393870] = "Increases healing done by Flash Heal$?c1[ and Shadow Mend][] by $s1%."
WoWFA_Data[393870] = "شفای Flash Heal$?c1[ و Shadow Mend][] را 15% افزایش می‌دهد."
WoWFA_Data[406788] = "Mind Blast یک شارژ اضافی به‌دست می‌آورد."
WoWFA_Data[407430] = "آسیب Shadow Word: Madness شما را 6% افزایش می‌دهد و حداکثر Insanity شما را 50 افزایش می‌دهد."
WoWFA_Data[407469] = "Shadow Apparitionها به اهداف متأثر از Shadow Word: Madness شما 30% آسیب بیشتری وارد می‌کنند."
WoWFA_Data[407470] = "هزینهٔ Insanity Shadow Word: Madness را 5 کاهش می‌دهد."
WoWFA_Data[409044] = "آسیب Shadow Word: Madness را 20% افزایش می‌دهد و باعث می‌شود آسیب خود را در طول 12 ثانیه وارد کند، اما هزینهٔ Insanity آن 5 افزایش می‌یابد."
WoWFA_Data[414553] = "Holy Wordهای شما 25% شانس دارند که کست بعدی Prayer of Mending شما کول‌داونش را نادیده بگیرد."
WoWFA_Data[415416] = "شفای اسپل‌های شما به‌اندازهٔ 3% افزایش می‌یابد."
WoWFA_Data[419110] = "کول‌داون Divine Hymn را به‌اندازهٔ 60 ثانیه کاهش می‌دهد."
WoWFA_En[421453] = "Ascend into the air and unleash a massive barrage of Penance bolts, causing $<penancedamage> Holy damage to enemies or $<penancehealing> healing to allies over $421434d.\n\nWhile ascended, gain a shield for $s1% of your health. In addition, you are unaffected by knockbacks or crowd control effects."
WoWFA_Data[421453] = "به هوا اوج می‌گیرید و رگباری عظیم از شلیک‌های Penance آزاد می‌کنید که در طول 6 ثانیه به دشمنان $<penancedamage> آسیب Holy یا به متحدان $<penancehealing> شفا می‌رساند.\n\nهنگام اوج گرفتن، سپری به‌اندازهٔ 100% از سلامتی‌تان به‌دست می‌آورید. علاوه بر این، از knockbackها و اثرات crowd control مصون هستید."
WoWFA_En[433905] = "$?c1[Your Flash Heal, Shadow Mend, and Power Word: Shield are $s1%][Your Flash Heal and Holy Word: Serenity are $s1%] more effective when cast on yourself."
WoWFA_Data[433905] = "$?c1[Flash Heal، Shadow Mend و Power Word: Shield شما وقتی روی خودتان کست شوند، 30% اثربخش‌ترند][Flash Heal و Holy Word: Serenity شما وقتی روی خودتان کست شوند، 30% اثربخش‌ترند]."
WoWFA_En[440662] = "$?a137032[Power Word: Shield absorbs $s2% additional damage.\n\nAll damage dealt by Penance, Smite and Holy Nova increased by $s3%.][Increases the healing done by Prayer of Mending by $s1%.\n\nAll damage dealt by Smite, Holy Fire and Holy Nova increased by $s4%.]\n"
WoWFA_Data[440662] = "$?a137032[Power Word: Shield 30% آسیب اضافی جذب می‌کند.\n\nتمام آسیب Penance، Smite و Holy Nova به‌اندازهٔ 15% افزایش می‌یابد.][شفای Prayer of Mending را 15% افزایش می‌دهد.\n\nتمام آسیب Smite، Holy Fire و Holy Nova به‌اندازهٔ 40% افزایش می‌یابد.]"
WoWFA_Data[440669] = "به‌مدت 6 ثانیه پس از کست کردن Leap of Faith، می‌توانید بار دوم آن را رایگان و بدون توجه به کول‌داونش کست کنید."
WoWFA_Data[440670] = "پَرهای Angelic Feather شما سرعت حرکت را 10% اضافی افزایش می‌دهند.\n\nوقتی متحدی از Angelic Feather شما عبور کند، شما نیز 100% از اثر آن را دریافت می‌کنید."
WoWFA_En[440671] = "$?a137032[Increases the duration of Atonement by ${$s1/1000} sec.][Increases the duration of your Renew by $s2%.]\n"
WoWFA_Data[440671] = "$?a137032[مدت Atonement را 4 ثانیه افزایش می‌دهد.][مدت Renew شما را 40% افزایش می‌دهد.]"
WoWFA_En[440681] = "Reduces the cooldown of $?a137032[Power Word: Shield by ${$s2/-1000}.1 sec.][Prayer of Mending by ${$s1/-1000}.1 sec.]"
WoWFA_Data[440681] = "کول‌داون $?a137032[Power Word: Shield را 1.5 ثانیه][Prayer of Mending را 1.5 ثانیه] کاهش می‌دهد."
WoWFA_En[440738] = "$?a137032[Pain Suppression reduces damage taken by an additional $s1%.][Guardian Spirit lasts an additional ${$s2/1000} sec.]"
WoWFA_Data[440738] = "$?a137032[Pain Suppression آسیب دریافتی را 10% دیگر کاهش می‌دهد.][Guardian Spirit 2 ثانیه بیشتر دوام می‌آورد.]"
WoWFA_En[440742] = "$?a137031[An additional $s1 stacks of Prayer of Mending is placed on a second ally within $A2 yards when casting Prayer of Mending.][$s3 additional Penance bolts are fired at an enemy within $A2 yards when healing an ally with Penance, or fired at an ally within $A2 yards when damaging an enemy with Penance.]"
WoWFA_Data[440742] = "$?a137031[هنگام کست کردن Prayer of Mending، 4 استک اضافی Prayer of Mending روی متحد دومی در فاصلهٔ 40 یارد قرار می‌گیرد.][3 شلیک اضافی Penance هنگام شفا دادن متحدی با Penance به دشمنی در فاصلهٔ 40 یارد شلیک می‌شود، یا هنگام آسیب زدن به دشمنی با Penance به متحدی در فاصلهٔ 40 یارد شلیک می‌شود.]"
WoWFA_En[440766] = "$?a137032[Power Word: Shield casts apply $s1 $Lstack:stacks; of Prayer of Mending to your target.\n\n$@spellicon33076 $@spellname33076\n$@spelldesc33076][Casting Prayer of Mending applies Power Word: Shield to your target.\n\n$@spellicon1246768 $@spellname1246768\n$@spelldesc1246768]"
WoWFA_Data[440766] = "$?a137032[کست‌های Power Word: Shield، 4 استک Prayer of Mending روی هدف شما اعمال می‌کنند.\n\n Prayer of Mending\nPlaces a ward on an ally that heals them for $33110s1 the next time they take damage, and then jumps to another ally within 30 yds. Jumps up to 4 times and lasts 30 ثانیه after each jump.][کست کردن Prayer of Mending، Power Word: Shield را روی هدف شما اعمال می‌کند.\n\n Power Word: Shield\nShields an ally for 15 ثانیه, absorbing 4 damage.]"
WoWFA_En[447444] = "$?c3[Tear open a rift][Mind Blast tears open an Entropic Rift] that follows the enemy for $450193d. Enemies caught in its path suffer $447448s1 Shadow damage every $459314t1 sec while within its reach."
WoWFA_Data[447444] = "$?c3[شکافی می‌گشایید][Mind Blast شکافی Entropic می‌گشاید] که به‌مدت 8 ثانیه دشمن را تعقیب می‌کند. دشمنانی که در مسیر آن گرفتار شوند، تا زمانی که در دسترس آن باشند هر 1 ثانیه $447448s1 آسیب Shadow متحمل می‌شوند."
WoWFA_En[448278] = "$?c3[Vampiric Touch and Shadow Word: Pain deal $s1% additional damage.][Power Word: Shield absorbs $s2% additional damage.]"
WoWFA_Data[448278] = "$?c3[Vampiric Touch و Shadow Word: Pain 20% آسیب اضافی وارد می‌کنند.][Power Word: Shield 20% آسیب اضافی جذب می‌کند.]"
WoWFA_En[448403] = "Each time $?c3[you cast Shadow Word: Madness][Penance damages or heals], Entropic Rift is empowered, increasing its damage and size by $?c1[$s4][$s3]%.\n\nAfter Entropic Rift ends it collapses, dealing $448405s1 Shadow damage split amongst enemy targets within $448405a1 yds."
WoWFA_Data[448403] = "هر بار که $?c3[Shadow Word: Madness کست می‌کنید][Penance آسیب می‌زند یا شفا می‌دهد]، Entropic Rift تقویت می‌شود و آسیب و اندازهٔ آن $?c1[10][20]% افزایش می‌یابد.\n\nپس از پایان Entropic Rift، فرومی‌ریزد و $448405s1 آسیب Shadow را میان دشمنان در فاصلهٔ 15 یارد تقسیم می‌کند."
WoWFA_Data[449806] = "Halo اکنون حول شما مرکز می‌گیرد و پس از رسیدن به حداکثر فاصله به سمت شما بازمی‌گردد؛ هر بار که از متحدان عبور کند به آن‌ها شفا می‌دهد و هر بار که از دشمنان عبور کند به آن‌ها آسیب می‌زند."
WoWFA_Data[449874] = "آسیب و شفای Halo به‌اندازهٔ 30% افزایش می‌یابد."
WoWFA_En[449880] = "While Entropic Rift is active, your $?c3[Shadow damage is increased by $s1%] [Atonement healing is increased by $s2%]."
WoWFA_Data[449880] = "وقتی Entropic Rift فعال است، $?c3[آسیب Shadow شما 5% افزایش می‌یابد] [شفای Atonement شما 20% افزایش می‌یابد]."
WoWFA_En[449912] = "Void Blast increases the duration of Entropic Rift by $?c1[${$s1}.1][${$s3}.1] sec, up to a maximum of $s2 sec."
WoWFA_Data[449912] = "Void Blast مدت Entropic Rift را $?c1[1][1] ثانیه افزایش می‌دهد؛ حداکثر تا 3 ثانیه."
WoWFA_En[450138] = "Summoning an Entropic Rift $?c1[extends the duration of your $s4 shortest Atonements by $s1 sec][grants you Shadowy Insight]."
WoWFA_Data[450138] = "احضار Entropic Rift، $?c1[مدت 5 کوتاه‌ترین Atonementهای شما را 1 ثانیه تمدید می‌کند][Shadowy Insight به شما می‌دهد]."
WoWFA_En[450405] = "Entropic Rift upgrades $?c3[Mind Blast][Smite] into Void Blast while it is active.\n\n$?c1[$@spellname450215:\n$@spelldesc450215][$@spellname450983:\n$@spelldesc450983]"
WoWFA_Data[450405] = "وقتی Entropic Rift فعال است، $?c3[Mind Blast][Smite] را به Void Blast ارتقا می‌دهد.\n\n$?c1[Void Blast:\nSends a blast of cosmic void energy at the enemy, causing 450215 Shadow damage.$?c3[\n\n|cFFFFFFFFGenerates ${$c/100*-1} Insanity.|r][]][Void Blast:\nSends a blast of cosmic void energy at the enemy, causing 450215 Shadow damage.$?c3[\n\n|cFFFFFFFFGenerates 0.02 Insanity.|r][]]"
WoWFA_En[450612] = "$?c1[While Entropic Rift is active, Atonement healing with Void Blast and Penance is $s2% more effective.][Void Blast generates ${$s1/100} additional Insanity.]"
WoWFA_Data[450612] = "$?c1[وقتی Entropic Rift فعال است، شفای Atonement با Void Blast و Penance به‌اندازهٔ 75% اثربخش‌تر است.][Void Blast 2 Insanity اضافی تولید می‌کند.]"
WoWFA_En[451018] = "$?c3[Void Torrent can be used while moving. ][]While Entropic Rift is active, you move $s1% faster."
WoWFA_Data[451018] = "$?c3[می‌توان Void Torrent را در حال حرکت استفاده کرد. ][]وقتی Entropic Rift فعال است، 20% سریع‌تر حرکت می‌کنید."
WoWFA_Data[451204] = "Entropic Rift سرعت دشمنان را تا حداکثر 70% کاهش می‌دهد؛ هرچه به مرکز آن نزدیک‌تر باشند، این کاهش بیشتر می‌شود."
WoWFA_En[451234] = "When Entropic Rift ends, a Voidwraith is summoned from the collapsed rift for $451235d.\n\n$@spellicon451235$@spellname451235\n$@spelldesc451235"
WoWFA_Data[451234] = "وقتی Entropic Rift پایان می‌یابد، از شکاف فروریخته یک Voidwraith به‌مدت 5 ثانیه احضار می‌شود.\n\nVoidwraith\nSummon a Voidwraith that casts Void Flay from afar. Void Flay deals bonus damage to high health enemies, up to a maximum of 50% if they are full health.$?s137033[\n\n|cFFFFFFFFGenerates 1 Insanity each time the Voidwraith attacks.|r][\n\n|cFFFFFFFFGenerates ${$34433s4/10}.1% Mana each time the Voidwraith attacks.|r]"
WoWFA_Data[451311] = "هر 3 ثانیه، از متحدی در فاصلهٔ 40 یارد که سلامتی بیشتری از شما دارد، مقداری معادل 4% از سلامتی شما می‌مکد."
WoWFA_Data[451569] = "3% از تمام آسیب Magic دریافتی را جذب می‌کنید. جذب آسیب Shadow، شما را به‌اندازهٔ 100% از مقدار جذب‌شده شفا می‌دهد."
WoWFA_En[451840] = "Shadow Word: Death consumes absorb shields from your target, dealing $32379s1 extra damage to them and granting you $?c3[$s3 Insanity][$s2% mana] if a shield was present."
WoWFA_Data[451840] = "Shadow Word: Death سپرهای جذب آسیب روی هدف شما را مصرف می‌کند؛ $32379s1 آسیب اضافی به او وارد می‌کند و اگر سپری وجود داشت، $?c3[5 Insanity][1% Mana] به شما می‌دهد."
WoWFA_Data[453109] = "کست کردن Halo همچنین باعث می‌شود برای 10 ثانیه، هر 5 ثانیه یک Halo با 100% اثربخشی حول شما ایجاد شود."
WoWFA_Data[453726] = "Power Word: Fortitude، 5% Stamina اضافی به شما می‌دهد."
WoWFA_En[453729] = "$?a137031[Increases the duration of Spirit of Redemption by ${$s1/1000} sec.][Increases the duration of Dispersion by ${$s2/1000} sec.]"
WoWFA_Data[453729] = "$?a137031[مدت Spirit of Redemption را 5 ثانیه افزایش می‌دهد.][مدت Dispersion را 2 ثانیه افزایش می‌دهد.]"
WoWFA_En[453783] = "Creating a Halo $?a137033[upgrades your next Mind Flay to Mind Flay: Insanity.\n\n$@spellicon391403 $@spellname391403\n$@spelldesc391403][grants Surge of Light.\n\n$@spellicon109186 $@spellname109186\n$@spelldesc109186]"
WoWFA_Data[453783] = "ایجاد Halo، $?a137033[Mind Flay بعدی شما را به Mind Flay: Insanity ارتقا می‌دهد.\n\n Mind Flay: Insanity\nAssaults the target's mind with Shadow energy, causing $o1 Shadow damage over 1.5 ثانیه and slowing their movement speed by 70%.\n\n|cFFFFFFFFGenerates 8 Insanity over the duration.|r][Surge of Light به شما می‌دهد.\n\n Surge of Light\nاسپل‌های شفای شما و Smite 8% شانس دارند که $?c1[Flash Heal یا Shadow Mend][Flash Heal]$?a1247178[ یا Prayer of Healing][] بعدی شما را فوری کنند و هزینهٔ Mana آن را $?a137030[50]?a137031[50][50]% کاهش دهند. تا 2 استک می‌شود.]"
WoWFA_En[453799] = "$?a137033[Increases the damage done by Mind Flay: Insanity by $s2%.\n\n][Your spells affected by Surge of Light heal for $s1% more while Surge of Light is active.]"
WoWFA_Data[453799] = "$?a137033[آسیب Mind Flay: Insanity را 30% افزایش می‌دهد.\n\n][اسپل‌های متأثر از Surge of Light، وقتی Surge of Light فعال است، 5% بیشتر شفا می‌دهند.]"
WoWFA_En[453828] = "$?a137031&?a1246517[Consuming Surge of Light reduces the cooldown of Holy Word: Serenity by ${$s1/-1000} sec.]?a137031&!a1246517[Consuming Surge of Light reduces the cooldown of Holy Word: Sanctify by ${$s1/-1000} sec.][Casting Mind Flay: Insanity has a $s2% chance to conjure Shadowy Apparitions.]"
WoWFA_Data[453828] = "$?a137031&?a1246517[مصرف Surge of Light، کول‌داون Holy Word: Serenity را 4 ثانیه کاهش می‌دهد.]?a137031&!a1246517[مصرف Surge of Light، کول‌داون Holy Word: Sanctify را 4 ثانیه کاهش می‌دهد.][کست کردن Mind Flay: Insanity 100% شانس دارد Shadowy Apparition احضار کند.]"
WoWFA_En[453845] = "$?a137033[Creating a Halo increases your spell damage by $453850s1% for $453850d, stacking up to $453850U times.][Creating a Halo increases your healing done by $453846s1% for $453846d, stacking up to $453846U times.]"
WoWFA_Data[453845] = "$?a137033[ایجاد Halo، آسیب اسپل شما را برای 10 ثانیه به‌اندازهٔ 2% افزایش می‌دهد؛ تا $453850U بار استک می‌شود.][ایجاد Halo، شفای شما را برای 10 ثانیه به‌اندازهٔ 2% افزایش می‌دهد؛ تا $453846U بار استک می‌شود.]"
WoWFA_En[453852] = "Halo damage reduces enemy movement speed by $453848s1% for $453848d, stacking up to $453848U times."
WoWFA_Data[453852] = "آسیب Halo، سرعت حرکت دشمن را برای 5 ثانیه به‌اندازهٔ 5% کاهش می‌دهد؛ تا $453848U بار استک می‌شود."
WoWFA_En[453917] = "$?a137031[Your healing done is increased by $s3% while Apotheosis is active.][Your damage dealt is increased by $s1% while Voidform is active.]"
WoWFA_Data[453917] = "$?a137031[وقتی Apotheosis فعال است، شفای شما 10% افزایش می‌یابد.][وقتی Voidform فعال است، آسیب شما 5% افزایش می‌یابد.]"
WoWFA_Data[453918] = "Psychic Scream در مکان شما تصویری از شما ایجاد می‌کند. پس از 4 ثانیه، این تصویر یک Psychic Scream سر می‌دهد."
WoWFA_En[454001] = "Creating a Halo extends the duration of $?a137031[Apotheosis][Voidform] by ${$s1/1000} sec. If $?a137031[Apotheosis][Voidform] is not active, up to $454002U seconds is stored.\n\nWhile out of combat or affected by a loss of control effect, the duration of $?a137031[Apotheosis][Voidform] is paused for up to $s2 sec."
WoWFA_Data[454001] = "ایجاد Halo، مدت $?a137031[Apotheosis][Voidform] را 1 ثانیه تمدید می‌کند. اگر $?a137031[Apotheosis][Voidform] فعال نباشد، تا $454002U ثانیه ذخیره می‌شود.\n\nوقتی خارج از مبارزه هستید یا تحت اثر از دست دادن کنترل هستید، مدت $?a137031[Apotheosis][Voidform] تا 20 ثانیه متوقف می‌ماند."
WoWFA_Data[458718] = "Desperate Prayer 10 ثانیه بیشتر دوام می‌آورد.\n\nاثر جذب Angelic Bulwark به‌اندازهٔ 15% از حداکثر سلامتی شما افزایش می‌یابد."
WoWFA_Data[459559] = "برد بیشتر اسپل‌ها را 15% افزایش می‌دهد."
WoWFA_En[471504] = "Holy Word: Serenity applies ${$s1/1000} sec of Renew to its target.\n\n$?a1246517[Ultimate Serenity][Holy Word: Sanctify] applies $?a440671[${$s2/1000}.1][${$s2/1000}] sec of Renew to allies it heals.\n\n$@spellicon139 $@spellname139\nFill the target with faith in the light, healing for $?a440671[${$139o1*$s1/15000/(1+$440671s2/100)}.1][${$139o1*$s1/15000}] over ${$s1/1000} sec."
WoWFA_Data[471504] = "Holy Word: Serenity به‌اندازهٔ 12 ثانیه Renew روی هدف خود اعمال می‌کند.\n\n$?a1246517[Ultimate Serenity][Holy Word: Sanctify] به متحدانی که شفا می‌دهد، به‌اندازهٔ $?a440671[6][6] ثانیه Renew اعمال می‌کند.\n\n Renew\nهدف را با ایمان به نور پر می‌کند و در طول 12 ثانیه به میزان $?a440671[${$139o1*$s1/15000/(1+$440671s2/100)}.1][${$139o1*$s1/15000}] شفا می‌دهد."
WoWFA_En[471668] = "Increases the healing done by Holy Word: Serenity$?a1246517[ by $s1%.][ and Holy Word: Sanctify by $s1%.\n\nIncreases the radius of Holy Word: Sanctify by $s2%.]"
WoWFA_Data[471668] = "شفای Holy Word: Serenity$?a1246517[ را 30% افزایش می‌دهد.][ و شفای Holy Word: Sanctify را 30% افزایش می‌دهد.\n\nشعاع Holy Word: Sanctify را 30% افزایش می‌دهد.]"
WoWFA_Data[472361] = "Smite مدت Atonement فعال را 2 ثانیه تمدید می‌کند."
WoWFA_Data[472433] = "بلافاصله Power Word: Radiance را با 150% اثربخشی روی هدف شما کست می‌کند و باعث می‌شود 2 کست بعدی Power Word: Radiance شما فوری باشند و 40% Mana کمتری مصرف کنند."
WoWFA_En[472568] = "Shadow Word: Pain Spreads to $?s373003[${1+$373003s2} nearby enemies][a nearby enemy] when you cast Penance on the target."
WoWFA_Data[472568] = "وقتی روی هدف Penance کست می‌کنید، Shadow Word: Pain به $?s373003[2 دشمن نزدیک][یک دشمن نزدیک] گسترش می‌یابد."
WoWFA_En[1215241] = "Your healing is increased by $s1% while Apotheosis is active.\n\nCasting Apotheosis causes your next $1216314U Prayer of Healing casts to be instant and heal for $1216314s2% more."
WoWFA_Data[1215241] = "وقتی Apotheosis فعال است، شفای شما 10% افزایش می‌یابد.\n\nکست کردن Apotheosis باعث می‌شود $1216314U کست بعدی Prayer of Healing شما فوری باشند و 25% بیشتر شفا دهند."
